    r=json.loads(Path(result_path).read_text()); v=json.loads(Path(verify_path).read_text()); pre=dict(r["pre_independent_obligations"]); passes={k:int(pre.get(k,0)) for k in REQUIRED if k!="INDEPENDENT_REPLAY_PASS"}; passes["INDEPENDENT_REPLAY_PASS"]=int(v.get("status")=="PASS" and v.get("error_count")==0 and v.get("v_independent_verifier")==1)
