    fields_ok=all(all(k in z for k in FIELDS) for z in (A,B,C)); exact_names=set(passes)==set(REQUIRED); allpasses=exact_names and len(passes)==27 and all(x==1 for x in passes.values()); no_gap=(r["failure_count"]==0 and not r["falsifiers"] and fields_ok and v["status"]=="PASS" and r["source_transport"]["manual_future_boundary_source_insertion"]==0 and all(h["actual_cascade"]["manual_derived_insertion"]==0 for h in r["holdouts"]))
